def totals(csv_text):
    rows = csv_text.splitlines()
    totals = {}
    for row in rows:
        if not row.strip():
            continue
        name, amount = row.split(",")
        totals[name.strip()] = totals.get(name.strip(), 0) + Decimal(amount)
    return {name: round(total, 2) for name, total in totals.items()}

